INSERT INTO instruments (instrument_id, authority_id, lg_id, kind, force, title, notes) VALUES ($q$SCC_PLANNING_SCHEME_2014$q$, $q$SCC$q$, $q$SUNSHINE_COAST$q$, 'PLANNING_SCHEME', 'STATUTORY_INSTRUMENT', $q$Sunshine Coast Planning Scheme 2014$q$, $q$The scheme commenced on 21 May 2014 (Citation and commencement: 'The commencement date for the planning scheme was 21 May 2014.'). The latest adopted amendment is No. 27 (adopted 27 July 2023, effective 23 January 2024). Neither the adopted-amendments page nor Appendix 2 lists anything later as at October 2026 (the web page was last updated 29 Sep 2026). The proposed NEW Sunshine Coast Planning Scheme was on public notification from 15 Jul to 19 Sep 2025 and is still at the submissions review / final State approval stage. Council's FAQ says: 'It is difficult to predict with any certainty how long these steps will take.' No commencement date was found, so the 2014 scheme remains in force at October 2026. TLPIs in effect: TLPI 01/2025 Accommodation Hotel Incentive Measures (from 4 Apr 2025) and TLPI 04/2025 Kawana Waters Town Centre (from 13 Apr 2026, affects DCP 1 Kawana Waters); neither targets dwelling house siting. State Priority Development Areas (e.g. Caloundra South/Aura, Maroochydore City Centre) and DCP 1 Kawana Waters (Part 10) have their own controls, which are not captured here.$q$);
INSERT INTO instrument_versions (instrument_version_id, instrument_id, version_label, effective_from, status, source_url, retrieved_at, notes) VALUES ($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$SCC_PLANNING_SCHEME_2014$q$, $q$Version 27 incorporating Sunshine Coast Planning Scheme (Major Amendment) No. 27 - Site Specific and Editorial Matters (Appendix 2 Table AP2.1); code PDF footers read 'Amended 23 January 2024'$q$, $q$2024-01-23$q$, 'ACTIVE', $q$https://www.sunshinecoast.qld.gov.au/development-advice/planning-documents/sunshine-coast-planning-scheme-2014$q$, $q$2026-10-08$q$, NULL);
