SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$QDC relationship: 1.6(4) Table 1.6.1 Building assessment provisions$q$, 'APPLICATION', $q$QDC alternative provisions Alternative provisions to the QDC for boundary clearance (setback) and site cover provisions for a dwelling house or a class 10 building or structure located on the same lot as a dwelling house. ... Section 9.3.6 Dwelling house code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007637/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$QDC relationship: 1.6(4) Table 1.6.1$q$, 'APPLICATION', $q$Provisions about performance criteria 4 and 8 under parts 1.1 and 1.2 of the QDC for a dwelling house or a class 10 building or structure located on the same lot as a dwelling house. ... Amenity and aesthetics provisions for a dwelling house or a class 10 building or structure located on the same lot as a dwelling house. ... Section 9.3.6 Dwelling house code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007637/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$QDC relationship: 1.6(3) Editor's note$q$, 'APPLICATION', $q$(c) specify alternative planning scheme provisions under section 33 of the Building Act 1975. This relates to alternative design solutions for boundary clearance and site cover provisions MP 1.1, 1.2 and 1.3 of the QDC.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007637/File/document$q$, NULL, NULL);
