SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Setback$q$, 'DEFINITION', $q$For a building or structure, the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Site cover$q$, 'DEFINITION', $q$The proportion of the site covered by a building(s), structure(s) attached to the building(s) and carport(s), calculated to the outer most projections of the building(s) and is expressed as a percentage. The term does not include:- (a) any structure or part thereof included in a landscaped open space area such as a gazebo or shade structure; (b) basement car parking areas located wholly below ground level; (c) eaves and sun shading devices.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Building height$q$, 'DEFINITION', $q$Means:- (a) if specified in metres--the vertical distance between the ground level and the highest point of the building roof (apex) or parapet at any point, but not including any load bearing antenna, aerial, chimney, flagpole or the like; (b) if specified in storeys--the number of storeys above ground level; or (c) if specified in both metres and storeys, both (a) and (b) apply. Note--Notwithstanding the definition of ground level, for the purpose of determining building height in Precinct CAL LPP-4 (Moffat Beach/Shelly Beach/Dicky Beach), ground level is the level of the land at the time the original estate was subdivided and roads created as determined by a cadastral surveyor, or if this level is not known, the natural level of the ground or probable natural level of the ground as determined by a cadastral surveyor.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Ground level$q$, 'DEFINITION', $q$The level of the natural ground, or, where the level of the natural ground has been changed, the level as lawfully changed.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Frontage$q$, 'DEFINITION', $q$Any boundary line, or part thereof, of a lot which coincides with the alignment of a road.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Storey$q$, 'DEFINITION', $q$A space that is situated between one floor level and the floor level next above, or if there is no floor above, the ceiling or roof above, but not a space that contains only:- (a) a lift shaft, stairway or meter room; (b) a bathroom, shower room, laundry, water closet, or other sanitary compartment; or (c) a combination of the above. A mezzanine is a storey. A roofed structure on or part of a rooftop that does not solely accommodate building plant and equipment is a storey. A basement is not a storey.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Basement$q$, 'DEFINITION', $q$A space that is situated between one floor level and the floor level next below where no part of the space projects more than one metre above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Dwelling house$q$, 'DEFINITION', $q$A residential use of premises for one household that contains a single dwelling. The use includes out-buildings and works normally associated with a dwelling house and may include a secondary dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.1 use definitions$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Dwelling house (code editor's note)$q$, 'DEFINITION', $q$Editor's note--in accordance with Schedule 1 (Definitions), a reference to a `dwelling house' in the planning scheme includes a reference to any secondary dwelling or home office associated with the dwelling house, and all outbuildings, structures and works normally associated with a dwelling house.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$9.3.6 footnote 3$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Residential zone$q$, 'DEFINITION', $q$Means each of the following zones:- (a) Low density residential zone; (b) Medium density residential zone; (c) High density residential zone; and (d) Tourist accommodation zone.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Secondary dwelling$q$, 'DEFINITION', $q$A dwelling used in conjunction with, and subordinate to, a dwelling house on the same lot. A secondary dwelling may be constructed under a dwelling house, be attached to a dwelling house or be freestanding.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Minor building work$q$, 'DEFINITION', $q$An alteration, addition or extension to an existing building(s):- (a) which results in an increase in the gross floor area, of the building(s) of less than five per cent of the gross floor area of the existing building(s) or 50m², whichever is the lesser; and (b) where the building work does not intrude into any boundary setback specified as an acceptable solution in an applicable use code.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 SC1.2$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$def Outbuilding / Class 10 / secondary frontage / wall height$q$, 'DEFINITION', $q$NOT DEFINED in Schedule 1. No definitions were found for 'outbuilding', 'class 10', 'secondary frontage' or 'wall height'; the code uses 'garage, carport or shed' and 'any road frontage'.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (searched)$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, NULL, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.5.1 Dwelling house (MCU) / Low density residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house | Accepted development | Dwelling house code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407271/File/document$q$, $q$Level: Accepted development (subject to requirements). Conditions: Requirements = Dwelling house code acceptable outcomes; overlays may change the category (Table 5.10.1)$q$, NULL);
