SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.5.18 Dwelling house (MCU) / Limited development (landscape residential) zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house | Accepted development | Dwelling house code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407292/File/document$q$, $q$Level: Accepted development (subject to requirements). Conditions: Dwelling house code$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.7.1 Building work Building work (not involving MCU), including Class 10a outbuildings associated with a dwelling house / All zones$q$, 'LEVEL_OF_ASSESSMENT', $q$Accepted development if:- (a) involving minor building work; or (b) associated with a use that is made accepted development by another table of assessment. | No requirements applicable / Accepted development if the applicable use code identifies acceptable outcomes applicable to accepted development. | The use code applicable to the use for which the building work is to be undertaken; Transport and parking code / Code assessment if not otherwise specified above. | ... The local plan code applicable to the site on which the building work is to be undertaken; Transport and parking code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407299/File/document$q$, $q$Level: Accepted development; accepted subject to requirements; otherwise code assessment. Conditions: Accepted with no requirements if minor building work, or if associated with a use made accepted by another table. Accepted subject to the use code's AOs where that code has AOs for accepted development (the Dwelling house code does). Code assessment otherwise.$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA 5.3.3(2) Accepted development that does not comply with AOs / All$q$, 'LEVEL_OF_ASSESSMENT', $q$(2) Accepted development that does not comply with one or more of the relevant acceptable outcomes in the relevant parts of the applicable code(s) becomes assessable development requiring code assessment unless otherwise specified.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007631/File/document$q$, $q$Level: Code assessment (limited to the non-complying matters). Conditions: $q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.10.1 Height of buildings and structures overlay Any development exceeding the mapped height / All (dwelling house is not excepted)$q$, 'LEVEL_OF_ASSESSMENT', $q$Any development if:- (a) exceeding the maximum height specified for the site on the applicable Height of Buildings and Structures Overlay Map 13; and (b) for a use or purpose other than:- ... | Impact assessment | The planning scheme$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407314/File/document$q$, $q$Level: Impact assessment. Conditions: exceeds the maximum height on the Height of Buildings and Structures Overlay Map$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.10.1 Building work (other than minor building work) in bushfire / flood / landslide overlay areas / All$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work not associated with a material change of use, other than minor building work, if within a flood and inundation area as identified on a Flood Hazard Overlay Map. | No change | Flood hazard overlay code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407314/File/document$q$, $q$Level: No change (the overlay code's requirements for accepted development apply). Conditions: $q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.10.1 Heritage and character areas overlay Building work in a character area / All$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work not associated with a material change of use if:- (a) within a character area as identified on a Heritage and Character Areas Overlay Map; and (b) involving any of the following external building work to a character building:- (i) extensions or other structures located forward of the existing front building alignment; (ii) extensions not forward of the existing front building alignment having a gross floor area exceeding 10m2; ... | Code assessment | Heritage and character areas overlay code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407314/File/document$q$, $q$Level: Code assessment. Conditions: external work to a character building, including extensions or structures forward of the existing front building alignment, or extensions over 10 m2 GFA that are not forward of it$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.10.1 Building work for a dwelling house in a coastal protection area / All$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work if:- (a) within a coastal protection area as identified on a Coastal Protection Overlay Map; and (b) involving the following:- (i) a dwelling house; ... | No change | Coastal protection overlay code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407314/File/document$q$, $q$Level: No change (Coastal protection overlay code AO1 applies). Conditions: except temporary/relocatable structures or landward extensions$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.5.17 Emerging community zone (Page 5-58, 'Amended 11 June 2018') Dwelling house (MCU) / Emerging community zone (land outside the Palmview declared master planned area)$q$, 'LEVEL_OF_ASSESSMENT', $q$Note--development in the Emerging community zone is intended to be subject to a master plan. An approved plan of development may provide variations to the levels of assessment specified in this table. ... All other land included in Emerging community zone / Residential activities / Dwelling house | Accepted development | Dwelling house code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407291/File/document$q$, $q$Level: Accepted development (subject to requirements). Conditions: Requirements = Dwelling house code acceptable outcomes. Overlays may change the category (Table 5.10.1). An approved plan of development may vary the levels (table note).$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 5.5.17; Tables 10.2.3.3B (Page 10-17) and 10.2.3.3C (Page 10-19) All development incl. dwelling house / Emerging community zone (Palmview declared master planned area)$q$, 'LEVEL_OF_ASSESSMENT', $q$Palmview declared master planned area | As specified in the table of assessment for the Structure Plan as varied by a variation approval. | As specified in the Structure Plan as varied by a variation approval. See Section 10.2 (Palmview Structure Plan) // Dwelling house (Consistent use) | Accepted development | • Palmview structure plan area code • Dwelling house code // 1. Development identified in a table of assessment as accepted development subject to requirements or assessable development requiring code assessment that exceeds the height limits specified in the Palmview structure plan area code as applicable to the site is assessable development requiring impact assessment except where the Planning Regulation 2017 specifies a different category of development and assessment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407421/File/document$q$, $q$Level: As specified in the Palmview Structure Plan tables. Conditions: Mixed Density Residential (Table 10.2.3.3B) and Medium Density Residential (Table 10.2.3.3C) precincts: dwelling house is Accepted development against the Palmview structure plan area code + Dwelling house code; becomes impact assessable if it exceeds the structure plan height limits.$q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$LOA Table 10.2.3.3K Building Work Table of Assessment (Pages 10-37 to 10-38) Building work not associated with MCU (incl. Class 10a outbuildings, pools) / Emerging community zone (Palmview declared ma$q$, 'LEVEL_OF_ASSESSMENT', $q$Minor Building Work where not otherwise specified. | Accepted development | No requirements applicable / Building Work where associated with an approved Material Change of Use of Premises. | Accepted development | No requirements applicable / Building Work where exceeding the height limits specified in the Palmview structure plan area code. | Impact assessment / Building Work not otherwise specified. | Accepted development or Code assessment where the applicable Use Code does not identify acceptable outcomes. | Palmview structure plan area code; The Use Code applicable to the use for which the Building Work is to be undertaken; Transport and parking code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407421/File/document$q$, $q$Level: Accepted (no requirements) for minor building work or work associated with an approved MCU; impact if exceeding height limits; otherwise accepted against Palmview code + use code, or code assessment. Conditions: $q$, NULL);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$overlay Height of buildings and structures overlay 8.2.8.3 PO2$q$, 'OTHER', $q$MH = OMH + FHA ... Note--for a dual occupancy or dwelling house on a site within the Low density residential zone, the flood hazard allowance calculated in accordance with the above formula is not to exceed 1 metre.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$8.2.8 Height of buildings and structures overlay code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407378/File/document$q$, $q$Sets a mapped maximum height for each site (Dwelling house code AO1 refers to it); adds a flood hazard allowance formula; exceeding the mapped height triggers impact assessment$q$, NULL);
