SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$overlay Flood hazard overlay Table 8.2.7.3.1 AO1$q$, 'OTHER', $q$AO1 The finished floor level of all habitable rooms is at least 500mm above the defined flood event (DFE) and defined storm tide event (DSTE).$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$8.2.7 Flood hazard overlay code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407377/File/document$q$, $q$Not a setback rule: habitable floor levels must be 500 mm above DFE/DSTE; the overlay also enables the height allowance$q$, NULL);

SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO2.1(a)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO2.1 Where located on a lot in a residential zone, a garage, carport or shed:- (a) is setback at least 6 metres from any road frontage; (b) does not exceed a height of 3.6 metres; and (c) has a total floor area that does not exceed 56m². Note--AO2.1(b) and (c) do not apply to a garage under the main roof of a dwelling house. Note--AO2.1(a) alternative provision to QDC.$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_garage_carport_shed_road_setback_res$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_garage_carport_shed_road_setback_res", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "GARAGE.FRONTAGE", "title": "9.3.6.3 Table 9.3.6.3.1 AO2.1(a)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_garage_carport_shed_road_setback_res", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"road_frontage_setback_garage_carport_shed\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"lot in a residential zone (LDR, MDR, HDR, Tourist accommodation)\", \"applies to ANY road frontage (primary and secondary)\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'garage, carport or shed (Class 10a) on a lot in a residential zone; (a) also applies to a garage under the main roof (the exclusion note covers only (b) and (c))' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: 'Note--AO2.1(a) alternative provision to QDC.' plus Part 1 Table 1.6.1, which lists s9.3.6 as containing the QDC alternative provisions. PDF text renders the superscript 2 in 'm2' as a replacement glyph; transcribed here as 'm²'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_garage_carport_shed_road_setback_res@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO2.1(b)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO2.1 Where located on a lot in a residential zone, a garage, carport or shed:- ... (b) does not exceed a height of 3.6 metres; ... Note--AO2.1(b) and (c) do not apply to a garage under the main roof of a dwelling house.$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$'Height' is not separately defined for this AO. Under 'Building height' (Schedule 1), a height in metres is the vertical distance between ground level and the highest point of the building roof (apex) or parapet.$q$, $q$dh_outbuilding_max_height_res$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_outbuilding_max_height_res", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "OUTBUILDING.SIZE", "title": "9.3.6.3 Table 9.3.6.3.1 AO2.1(b)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": 3.6, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A"], "sources": [{"key": "dh_outbuilding_max_height_res", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"outbuilding_height\", \"operator\": \"<=\", \"value\": 3.6, \"unit\": \"m\", \"conditions\": [\"lot in a residential zone\"], \"exceptions\": [\"garage under the main roof of a dwelling house\"], \"formula_text\": null}\nStructure scope 'garage, carport or shed in a residential zone (not a garage under the main roof)' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Only AO2.1(a) is tagged as an alternative provision. AO2.1(b)/(c) are requirements for accepted development; if they are not met, the work becomes code assessable for that matter (s5.3.3(2)). Table 1.6.1 also lists 'Amenity and aesthetics provisions for a dwelling house or a class 10 building' as being in s9.3.6, so (b)/(c) may also act as amenity and aesthetics provisions for building assessment."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_outbuilding_max_height_res@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO2.1(c)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO2.1 Where located on a lot in a residential zone, a garage, carport or shed:- ... (c) has a total floor area that does not exceed 56m². Note--AO2.1(b) and (c) do not apply to a garage under the main roof of a dwelling house.$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$'total floor area' is not a defined term. It is unclear whether 56 m² applies per structure or to all garages, carports and sheds on the lot combined.$q$, $q$dh_outbuilding_max_floor_area_res$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_outbuilding_max_floor_area_res", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "OUTBUILDING.SIZE", "title": "9.3.6.3 Table 9.3.6.3.1 AO2.1(c)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": 56, "unit": "m2", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A"], "sources": [{"key": "dh_outbuilding_max_floor_area_res", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"outbuilding_total_floor_area\", \"operator\": \"<=\", \"value\": 56, \"unit\": \"m2\", \"conditions\": [\"lot in a residential zone\"], \"exceptions\": [\"garage under the main roof of a dwelling house\"], \"formula_text\": null}\nStructure scope 'garage, carport or shed in a residential zone (not a garage under the main roof)' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Need to confirm whether 'total floor area' is per building or combined. PDF text renders the superscript 2 in 'm2' as a replacement glyph; transcribed here as 'm²'."}$q$::jsonb);
