SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO2.2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO2.2 Where located on a lot in a residential zone, the total width of a garage door facing a street (and that is visible from the road frontage) does not exceed 6 metres within any one plane, with any additional garage door being set back a further 1 metre from the street frontage to break up the apparent width of the garage facade.$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_garage_door_width_res$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_garage_door_width_res", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "GARAGE.FRONTAGE", "title": "9.3.6.3 Table 9.3.6.3.1 AO2.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": "<=", "value": 6, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A"], "sources": [{"key": "dh_garage_door_width_res", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"garage_door_width_per_plane\", \"operator\": \"<=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"lot in a residential zone\", \"garage door faces a street and is visible from the road frontage\", \"any additional garage door is set back a further 1 m from the street frontage\"], \"exceptions\": [], \"formula_text\": \"total garage door width within any one plane <= 6 m; each additional garage door set back >= 1 m further than the first plane\"}\nStructure scope 'garage doors facing a street and visible from the road frontage' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not tagged as an alternative provision. No limit on garage width relative to lot frontage is stated."}$q$::jsonb);
