SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO3 Where located in a residential zone, the dwelling house (other than a garage, carport or shed) is setback to any road frontage at least:- (a) 4.5 metres for the ground storey; and (b) 6 metres for any levels above the ground storey. Note--AO3 alternative provision to QDC.$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_front_setback_res$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_front_setback_res", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "SETBACK.FRONTAGE", "title": "9.3.6.3 Table 9.3.6.3.1 AO3", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "ground storey >= 4.5 m; upper storeys >= 6 m from any road frontage", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_front_setback_res", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"road_frontage_setback_dwelling\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"ground storey >= 4.5 m\", \"levels above the ground storey >= 6 m\", \"applies to any road frontage, so it includes the secondary frontage on corner lots\"], \"exceptions\": [\"garage, carport or shed (see AO2.1(a): 6 m)\"], \"formula_text\": \"ground storey >= 4.5 m; upper storeys >= 6 m from any road frontage\"}\nStructure scope 'dwelling house (other than a garage, carport or shed)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: 'Note--AO3 alternative provision to QDC.' There is no separate, reduced secondary-frontage setback; 'any road frontage' applies. Decks, patios and pergolas attached to the house are not addressed separately; as part of the dwelling house they would fall under AO3."}$q$::jsonb);
