SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO2.1(a) and AO3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO3 ... the dwelling house (other than a garage, carport or shed) is setback to any road frontage at least:- (a) 4.5 metres for the ground storey; and (b) 6 metres for any levels above the ground storey. / AO2.1 ... a garage, carport or shed:- (a) is setback at least 6 metres from any road frontage$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_secondary_frontage_setback_res$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_secondary_frontage_setback_res", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "SETBACK.SECONDARY_ROAD", "title": "9.3.6.3 Table 9.3.6.3.1 AO2.1(a) and AO3", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_SECONDARY_FRONTAGE", "operator": ">=", "value": {"op": "unencoded", "text": "house: ground storey 4.5 m, upper storeys 6 m; garage/carport/shed: 6 m", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_secondary_frontage_setback_res", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"secondary_frontage_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"the code says 'any road frontage', so the same values apply to every road frontage\"], \"exceptions\": [], \"formula_text\": \"house: ground storey 4.5 m, upper storeys 6 m; garage/carport/shed: 6 m\"}\nStructure scope 'dwelling house and garage/carport/shed on corner lots' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Derived rule: the code has no separate secondary-frontage provision. Confirm whether council and certifiers accept the QDC/QHC secondary-frontage concessions on corner lots in practice."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_secondary_frontage_setback_res@2024-01-23$q$;
