SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 (absence)$q$, 'OTHER', $q$(The Dwelling house code has no side or rear boundary setback acceptable outcome for residential zones. Side and rear setbacks AO5.1 and AO5.2 apply only to the Rural, Rural residential and Limited development (landscape residential) zones.)$q$, 'VERIFIED_VERBATIM', $q$Pages 9-23 to 9-24$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_side_rear_setback_res_none$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_side_rear_setback_res_none", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "SETBACK.SIDE", "title": "9.3.6.3 Table 9.3.6.3.1 (absence)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_SIDE", "operator": "=", "value": {"op": "unencoded", "text": "(The Dwelling house code has no side or rear boundary setback acceptable outcome for residential zones. Side and rear setbacks AO5.1 and AO5.2 apply only to the Rural, Rural residential and Limited development (landscape residential) zones.)", "extracted_value": null, "extracted_operator": "="}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_side_rear_setback_res_none", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side_rear_setback\", \"operator\": \"=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"defer to QDC/QHC Part 1.1 / 1.2\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'dwelling house and Class 10a in residential zones' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Council's sheds web page (COUNCIL_FACTSHEET, updated 29 Sep 2026) says that in residential zones side and rear boundaries are 'per Queensland Development Code MP 1.1 or MP 1.2'. So QHC Part 1.1/1.2 governs side and rear setbacks, built-to-boundary walls and site cover in residential zones."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_side_rear_setback_res_none@2024-01-23$q$;
