SELECT define_rule($q${"rule_id": "SCC.dh_site_cover_none", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "SITE_COVER", "title": "9.3.6 (absence)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SITE_COVER", "operator": "=", "value": {"op": "unencoded", "text": "(Neither the Dwelling house code nor the Low density or Medium density residential zone codes has a site cover acceptable outcome.)", "extracted_value": null, "extracted_operator": "="}, "unit": "%", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}, {"level": "ZONE", "zone": "SCC:RURAL"}, {"level": "ZONE", "zone": "SCC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:LIMITED_DEVELOPMENT_LANDSCAPE_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_site_cover_none", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"site_cover\", \"operator\": \"=\", \"value\": null, \"unit\": \"%\", \"conditions\": [\"defer to QDC/QHC\"], \"exceptions\": [\"Blackall Range local plan area: total footprint cap of 280 m² (AO16.2)\"], \"formula_text\": null}\nStructure scope 'dwelling house including Class 10a' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Checked the Dwelling house code and the LDR, MDR, RR and LDLR zone codes. The zone codes contain only purpose and overall outcomes, with no acceptable outcomes for dwelling houses."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_site_cover_none@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO1 The height of the dwelling house does not exceed the height specified for the site on the applicable Height of Buildings and Structures Overlay Map.$q$, 'VERIFIED_VERBATIM', $q$Page 9-22$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Building height (Schedule 1): '(a) if specified in metres--the vertical distance between the ground level and the highest point of the building roof (apex) or parapet at any point...'$q$, $q$dh_building_height_overlay$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_building_height_overlay", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "HEIGHT.BUILDING", "title": "9.3.6.3 Table 9.3.6.3.1 AO1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "height <= OMH (mapped); in a flooding and inundation area MH = OMH + FHA, with FHA <= 1 m for a dwelling house in the LDR zone", "extracted_value": null, "extracted_operator": "<="}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}, {"level": "ZONE", "zone": "SCC:RURAL"}, {"level": "ZONE", "zone": "SCC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:LIMITED_DEVELOPMENT_LANDSCAPE_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:EMERGING_COMMUNITY"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_building_height_overlay", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"<=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"the value is site-specific, from the Height of Buildings and Structures Overlay Map (Schedule 2)\"], \"exceptions\": [\"flood hazard allowance under 8.2.8 PO2 (max 1 m for a dwelling house in the LDR zone)\"], \"formula_text\": \"height <= OMH (mapped); in a flooding and inundation area MH = OMH + FHA, with FHA <= 1 m for a dwelling house in the LDR zone\"}\nStructure scope 'dwelling house (includes outbuildings by definition)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Mapped height values were NOT verified (8.5 m is commonly cited for low density areas): the overlay maps are JavaScript/image-based. Council's sheds page (COUNCIL_FACTSHEET) mentions 'Maximum 8.5m building height' for rural and rural residential zones. Under Table 5.10.1, exceeding the mapped height makes 'Any development' impact assessable."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_building_height_overlay@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$8.2.8.3 Table 8.2.8.3.1 PO2$q$, 'PERFORMANCE_OUTCOME', $q$Despite PO1 above, for development on a site within a flooding and inundation area, as identified on a Flood Hazard Overlay Map, the maximum height of a building or structure is calculated in accordance with the following formula:- MH = OMH + FHA ... Note--for a dual occupancy or dwelling house on a site within the Low density residential zone, the flood hazard allowance calculated in accordance with the above formula is not to exceed 1 metre.$q$, 'VERIFIED_VERBATIM', $q$Page 8-44$q$, NULL, $q$8.2.8 Height of buildings and structures overlay code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407378/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$height_overlay_flood_allowance$q$);
SELECT define_rule($q${"rule_id": "SCC.height_overlay_flood_allowance", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "HEIGHT.BUILDING", "title": "8.2.8.3 Table 8.2.8.3.1 PO2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DISCRETIONARY", "provision_kind": "PERFORMANCE_OUTCOME", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "MH = OMH + FHA; FHA = vertical difference between ground level and the minimum design floor level (Column 3B, Table 8.2.7.3.3); for a dwelling house in the LDR zone, FHA <= 1 m", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "ASSESS_AGAINST_PERFORMANCE_OUTCOME", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "OVERLAY", "overlay": "SCC:OV:FLOOD_HAZARD_OVERLAY_FLOODING_AND_INUNDATION_AREA"}], "subjects": ["CLASS_1"], "sources": [{"key": "height_overlay_flood_allowance", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_height_flood_adjusted\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"site is within a flooding and inundation area\"], \"exceptions\": [], \"formula_text\": \"MH = OMH + FHA; FHA = vertical difference between ground level and the minimum design floor level (Column 3B, Table 8.2.7.3.3); for a dwelling house in the LDR zone, FHA <= 1 m\"}\nStructure scope 'dwelling house / dual occupancy in the LDR zone within a flooding and inundation area' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: This code applies to assessable development. Note 13 of Table 5.10.1 brings the formula into the height-exceedance trigger."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.height_overlay_flood_allowance@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO6$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO6 Buildings and structures exceeding 1 metre in height above ground level (other than pool fencing which is at least 75% transparent) are setback a minimum of 4.5 metres from the property boundary adjacent to the canal or artificial waterway/waterbody. Note--AO6 alternative provision to QDC.$q$, 'VERIFIED_VERBATIM', $q$Page 9-24$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_canal_setback$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_canal_setback", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "POOL.SETBACK", "title": "9.3.6.3 Table 9.3.6.3.1 AO6", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": 4.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}, {"level": "ZONE", "zone": "SCC:RURAL"}, {"level": "ZONE", "zone": "SCC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:LIMITED_DEVELOPMENT_LANDSCAPE_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:EMERGING_COMMUNITY"}], "subjects": ["ANY"], "sources": [{"key": "dh_canal_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"canal_waterway_boundary_setback\", \"operator\": \">=\", \"value\": 4.5, \"unit\": \"m\", \"conditions\": [\"structure is more than 1 m above ground level\", \"boundary is adjacent to a canal or artificial waterway/waterbody (e.g. lakes)\"], \"exceptions\": [\"pool fencing at least 75% transparent\", \"structures not more than 1 m above ground level\"], \"formula_text\": null}\nLot conditions (not encoded): lot with a boundary adjacent to a canal or artificial waterway/waterbody\nStructure scope 'buildings and structures more than 1 m above ground level, including pools and decks; excludes pool fencing that is at least 75% transparent' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: 'Note--AO6 alternative provision to QDC.' In practice this also controls raised pools, decks, sheds and pergolas near canal boundaries."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_canal_setback@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO4.1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO4.1 Where located on a lot in the Rural zone, and the lot has an area of more than 2 hectares, the dwelling house (including any associated garage, carport or shed) is set back at least:- (a) 40 metres from a State controlled road or an extractive industry transport route; (b) 20 metres from any other road; or (c) if an extension not exceeding 50m2 gross floor area and within, under or structurally part of an existing dwelling house, the setback of the existing dwelling house on the site. Note--AO4.1 and AO4.2 alternative provisions to QDC.$q$, 'VERIFIED_VERBATIM', $q$Page 9-23$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_rural_large_road_setback$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_rural_large_road_setback", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "SETBACK.FRONTAGE", "title": "9.3.6.3 Table 9.3.6.3.1 AO4.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO4.1 Where located on a lot in the Rural zone, and the lot has an area of more than 2 hectares, the dwelling house (including any associated garage, carport or shed) is set back at least:- (a) 40 metres from a State controlled road or an extractive industry transport route; (b) 20 metres from any other road; or (c) if an extension not exceeding 50m2 gross floor area and within, under or structurally part of an existing dwelling house, the setback of the existing dwelling house on the site. Note--AO4.1 and AO4.2 alternative provisions to QDC.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:RURAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_rural_large_road_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"road_setback_rural_large\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"40 m from a State-controlled road or extractive industry transport route\", \"20 m from any other road\"], \"exceptions\": [\"extension <= 50 m² GFA within, under or structurally part of the existing house: existing setback\"], \"formula_text\": null}\nLot conditions (not encoded): lot area > 2 ha\nStructure scope 'dwelling house including any associated garage, carport or shed' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES"}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_rural_large_road_setback@2024-01-23$q$;
