SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO19.1, AO19.2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO19.1 Any secondary dwelling has a maximum gross floor area of 45m2. AO19.2 Any secondary dwelling does not exceed 4 metres in height from ground level.$q$, 'VERIFIED_VERBATIM', $q$Page 9-28$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_secondary_dwelling_lpp2$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_secondary_dwelling_lpp2", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "HEIGHT.BUILDING", "title": "9.3.6.3 Table 9.3.6.3.1 AO19.1, AO19.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 4, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_1"], "sources": [{"key": "dh_secondary_dwelling_lpp2", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"secondary_dwelling_height\", \"operator\": \"<=\", \"value\": 4, \"unit\": \"m\", \"conditions\": [\"secondary dwelling; GFA <= 45 m2\"], \"exceptions\": [], \"formula_text\": null}\nLocal plan: Appears under the Caloundra local plan Precinct CAL LPP-2 heading (to verify)\nStructure scope 'secondary dwelling' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not Class 10a. Included because PO19/AO19 follow the CAL LPP-2 heading with no new heading; the area it applies to needs confirming."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_secondary_dwelling_lpp2@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$9.3.6.3 Table 9.3.6.3.1 AO15$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO15 Except where located on a site having a slope of greater than 15% as identified on an applicable Landslide Hazard and Steep Land Overlay Map:- (a) the extent of excavation (cut) or fill does not involve a total change of more than 1.0 metre relative to ground level at any point; and (b) no part of any un-retained cut or fill batter is within 1.5 metres of any property boundary except cut and fill involving a change in ground level of less than 200mm. OR Filling and/or excavation is confined to within the plan area of the dwelling house with ground level being retained around external walls of the building. OR Where on a lot in an identified drainage deficient area, filling is undertaken in accordance with a current drainage deficient area flood information certificate issued by the Council for the site.$q$, 'VERIFIED_VERBATIM', $q$Pages 9-26 to 9-27$q$, NULL, $q$9.3.6 Dwelling house code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407391/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$dh_filling_excavation$q$);
SELECT define_rule($q${"rule_id": "SCC.dh_filling_excavation", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "OTHER", "title": "9.3.6.3 Table 9.3.6.3.1 AO15", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "<=", "value": 1.0, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}, {"level": "ZONE", "zone": "SCC:RURAL"}, {"level": "ZONE", "zone": "SCC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:LIMITED_DEVELOPMENT_LANDSCAPE_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:EMERGING_COMMUNITY"}], "subjects": ["POOL", "CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_filling_excavation", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"cut_fill_depth\", \"operator\": \"<=\", \"value\": 1.0, \"unit\": \"m\", \"conditions\": [\"no un-retained batter within 1.5 m of a boundary unless the change is < 200 mm\"], \"exceptions\": [\"slope > 15% on the Landslide overlay map\", \"cut/fill confined to the plan area of the house\", \"drainage deficient area certificate\"], \"formula_text\": null}\nStructure scope 'filling or excavation associated with a dwelling house (including outbuildings and pools)' mapped by keyword to ['POOL', 'CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO"}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.dh_filling_excavation@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$8.2.5.3 Table 8.2.5.3.1 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$AO1 All buildings and other permanent structures are located landward of the coastal building line for the site. ... OR Where there is no coastal building line for the site, and the site adjoins the beachfront or a beachfront reserve, all buildings and permanent structures are located:- (a) landward or equal to the seaward alignment of any buildings on neighbouring properties; or (b) where there are no neighbouring properties, at least 6 metres from the seaward property boundary of the site. Note--`permanent structures' include swimming pools and retaining walls.$q$, 'VERIFIED_VERBATIM', $q$Table 8.2.5.3.1$q$, NULL, $q$8.2.5 Coastal protection overlay code$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22407375/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$coastal_dh_seaward_setback$q$);
SELECT define_rule($q${"rule_id": "SCC.coastal_dh_seaward_setback", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "POOL.SETBACK", "title": "8.2.5.3 Table 8.2.5.3.1 AO1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": {"op": "unencoded", "text": "AO1 All buildings and other permanent structures are located landward of the coastal building line for the site. ... OR Where there is no coastal building line for the site, and the site adjoins the beachfront or a beachfront reserve, all buildings and permanent structures are located:- (a) landward or equal to the seaward alignment of any buildings on neighbouring properties; or (b) where there are no neighbouring properties, at least 6 metres from the seaward property boundary of the site. Note--`permanent structures' include swimming pools and retaining walls.", "extracted_value": 6, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "OVERLAY", "overlay": "SCC:OV:COASTAL_PROTECTION_OVERLAY_COASTAL_PROTECTION_AREA"}], "subjects": ["ANY"], "sources": [{"key": "coastal_dh_seaward_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"seaward_setback\", \"operator\": \"conditional\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"landward of the declared coastal building line; otherwise landward of or equal to the neighbours' seaward alignment; otherwise >= 6 m from the seaward boundary\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): site within a coastal protection area; the second limb applies where there is no coastal building line and the site adjoins the beachfront or a beachfront reserve\nStructure scope 'all buildings and permanent structures of a dwelling house, including swimming pools and retaining walls' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Table 5.10.1: building work for a dwelling house in a coastal protection area is 'No change' to the category of assessment, but this overlay code's requirements apply."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.coastal_dh_seaward_setback@2024-01-23$q$;
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$SC1.2 'Minor building work'$q$, 'DEFINITION', $q$Minor building work: An alteration, addition or extension to an existing building(s):- (a) which results in an increase in the gross floor area, of the building(s) of less than five per cent of the gross floor area of the existing building(s) or 50m², whichever is the lesser; and (b) where the building work does not intrude into any boundary setback specified as an acceptable solution in an applicable use code.$q$, 'VERIFIED_VERBATIM', $q$Page SC1-35$q$, NULL, $q$Schedule 1 Definitions$q$, NULL, $q$https://publicdocs.scc.qld.gov.au/hpecmwebdrawer/Record/22007624/File/document$q$, $q$Setback per Schedule 1: 'the shortest distance measured horizontally from the outermost projection of a building or structure to the vertical projection of the boundary of the lot.'$q$, $q$minor_building_work_definition$q$);
SELECT define_provision($q$SCC_PLANNING_SCHEME_2014@2024-01-23$q$, $q$n/a$q$, 'OTHER', $q$(via WebFetch summary) 'not exceed a height of 3.6 metres' and 'have a total floor area that does not exceed 56m²'; 'at least 6 metres from any road frontage property boundary'; Side and rear boundaries per Queensland Development Code MP 1.1 or MP 1.2; Reference Standards: Queensland Development Code MP 1.1 (lots under 450m²) and MP 1.2 (450m² and over); rural: 'Maximum 8.5m building height'$q$, 'COUNCIL_FACTSHEET', $q$Last updated 29 September 2026$q$, NULL, $q$Council webpage: Sheds (Class 10a)$q$, NULL, $q$https://sunshinecoast.qld.gov.au/development/building/sheds$q$, $q$$q$, $q$factsheet_sheds_residential$q$);
SELECT define_rule($q${"rule_id": "SCC.factsheet_sheds_residential", "instrument_version": "SCC_PLANNING_SCHEME_2014@2024-01-23", "topic": "OTHER", "title": "n/a", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "(via WebFetch summary) 'not exceed a height of 3.6 metres' and 'have a total floor area that does not exceed 56m²'; 'at least 6 metres from any road frontage property boundary'; Side and rear boundaries per Queensland Development Code MP 1.1 or MP 1.2; Reference Standards: Queensland Development Code MP 1.1 (lots under 450m²) and MP 1.2 (450m² and over); rural: 'Maximum 8.5m building height'", "extracted_value": null, "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-01-23", "verification": "COUNCIL_FACTSHEET", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SUNSHINE_COAST"}, {"level": "ZONE", "zone": "SCC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:HIGH_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "SCC:TOURIST_ACCOMMODATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "factsheet_sheds_residential", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"n/a\", \"operator\": \"=\", \"value\": null, \"unit\": null, \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'sheds, garages, carports (Class 10a)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: This council page was updated on 29 Sep 2026, after the QHC commenced, but still cites QDC MP 1.1/MP 1.2 rather than the Queensland Housing Code. It was fetched through a summarising tool, so some wording may be paraphrased."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SCC.factsheet_sheds_residential@2024-01-23$q$;

INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$The mapped maximum heights (Height of Buildings and Structures Overlay Maps, Schedule 2) were not fetched because the maps are JavaScript/image only. The 8.5 m commonly cited for low density areas is UNVERIFIED; the only mention found is on a council web page, for rural zones.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Whether the AO2.1(c) 56 m2 'total floor area' applies per structure or to all garages, carports and sheds on the lot combined.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Which area PO19/AO19 (secondary dwelling, 45 m2 / 4 m) applies to: it appears under the CAL LPP-2 heading.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$The scheme has not yet been amended to reference the Queensland Housing Code. The State transitional provisions (SL 2026 No. 115) need to be confirmed verbatim, specifically how the 'alternative provision to QDC' notes map to QHC Part 1.1/1.2 until 1 Sept 2029.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Pool setbacks: the scheme has no pool provision for residential lots apart from the AO6 canal setback (structures over 1 m) and coastal overlay AO1. Pool siting otherwise follows the QHC / Building Regulation.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Plans of development and structure plans (Palmview, Kawana DCP 1, State PDAs such as Caloundra South) may set different siting rules; these are not covered.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$The Low and Medium density residential zone codes contain only purpose and overall outcomes, with no numeric siting AOs. The High density and Tourist accommodation zones were not checked in depth.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Mapped Height of Buildings and Structures Overlay value for EC land is not verified (maps are JavaScript only). It is commonly 8.5 m, but this needs a map/ePlan check per site.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Lots in EC created under a variation approval or approved plan of development (including Palmview) may have POD-specific setbacks and site cover (Dwelling house code footnote 4). These are not in the scheme text and are not alternative provisions under Table 1.6.1. The tool should flag 'check approved plan of development' for EC lots.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Palmview: only the Mixed Density and Medium Density Residential precinct tables list a dwelling house. Other precincts were not checked for dwelling houses beyond a text search. AO24 (20 m from the SEQwater bulk pipeline, OPM P4) has no 's' suffix, so it is not an accepted-development requirement, but it may matter for code assessment.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$Whether any EC land lies in the Blackall Range local plan area (AO16.1/AO16.2) or a canal/waterbody area was not checked.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$QDC vs QHC: the scheme is unamended since No. 27, so it still refers to QDC MP1.1/1.2. The State transitional position (SL 2026 No. 115) is unverified verbatim (see sunshine_coast.json qdc_qhc_relationship).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SUNSHINE_COAST$q$, $q$SCC_PLANNING_SCHEME_2014$q$, 'MEDIUM', $q$State PDAs within or adjoining EC (e.g. Caloundra South / Aura, Beerwah East) are outside the planning scheme and were not covered.$q$);
